package com.acme.home

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch

class HomeViewModel(
    private val profileRepo: ProfileRepository,
    private val feedRepo: FeedRepository,
    private val notificationsRepo: NotificationsRepository,
) : ViewModel() {
    private val _state = MutableStateFlow(HomeState.Loading)
    val state: StateFlow<HomeState> = _state

    fun load(userId: String) {
        viewModelScope.launch {
            val profile = profileRepo.profile(userId)
            val feed = feedRepo.latest(userId, limit = 20)
            val unread = notificationsRepo.unreadCount(userId)
            _state.value = HomeState.Ready(profile, feed, unread)
        }
    }
}

package com.acme.pricing

class PriceRefreshService(
    private val supplierApi: SupplierApi,
    private val products: ProductRepository,
) {
    suspend fun refreshAll(skus: List<String>): Map<String, Long> {
        val prices = mutableMapOf<String, Long>()
        for (sku in skus) {
            prices[sku] = supplierApi.fetchPriceCents(sku)
        }
        products.updatePrices(prices)
        return prices
    }
}

