package com.acme.checkout

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.launch

class CheckoutViewModel(
    private val cartRepo: CartRepository,
    private val payments: PaymentsApi,
    private val orders: OrdersApi,
) : ViewModel() {
    fun placeOrder(cartId: String) {
        viewModelScope.launch {
            val cart = cartRepo.load(cartId)
            val intent = payments.createIntent(amountCents = cart.totalCents, currency = cart.currency)
            val order = orders.create(cartId = cart.id, paymentIntentId = intent.id)
            cartRepo.clear(cart.id)
            _events.emit(CheckoutEvent.Placed(order.id))
        }
    }
}

package com.acme.home

import kotlinx.coroutines.async
import kotlinx.coroutines.coroutineScope

class HomeLoader(
    private val profileRepo: ProfileRepository,
    private val feedRepo: FeedRepository,
    private val notificationsRepo: NotificationsRepository,
) {
    suspend fun load(userId: String): HomeState.Ready = coroutineScope {
        val profile = async { profileRepo.profile(userId) }
        val feed = async { feedRepo.latest(userId, limit = 20) }
        val unread = async { notificationsRepo.unreadCount(userId) }
        HomeState.Ready(profile.await(), feed.await(), unread.await())
    }
}

package com.acme.pricing

import kotlinx.coroutines.delay

class SupplierSync(private val supplierApi: SupplierApi) {
    // Supplier API allows 1 request/second per key; calls must stay sequential.
    suspend fun syncPrices(skus: List<String>): Map<String, Long> {
        val out = LinkedHashMap<String, Long>()
        for (sku in skus) {
            out[sku] = supplierApi.fetchPriceCents(sku)
            delay(1_000)
        }
        return out
    }
}

package com.acme.ledger

class LedgerMigration(private val ledger: LedgerRepository) {
    /**
     * Entries are applied strictly in order: each posting updates the running
     * balance that the next one validates against.
     */
    suspend fun replay(entries: List<LedgerEntry>) {
        for (entry in entries.sortedBy { it.sequence }) {
            ledger.apply(entry)
        }
    }
}

package com.acme.gallery

import kotlinx.coroutines.async
import kotlinx.coroutines.awaitAll
import kotlinx.coroutines.coroutineScope
import kotlinx.coroutines.sync.Semaphore
import kotlinx.coroutines.sync.withPermit

class ThumbnailPrefetcher(private val imageApi: ImageApi) {
    private val permits = Semaphore(6)

    suspend fun prefetch(ids: List<String>): List<Thumbnail> = coroutineScope {
        ids.map { id -> async { permits.withPermit { imageApi.downloadThumbnail(id) } } }.awaitAll()
    }
}

package com.acme.onboarding

class SeedDataLoader(private val api: ContentApi, private val store: ContentStore) {
    // Exactly two fixed locales ship in v1; serial is fine and keeps logs readable.
    suspend fun preload() {
        for (locale in listOf("en", "de")) {
            store.save(locale, api.fetchStrings(locale))
        }
    }
}

package com.acme.search

import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.flow.asFlow
import kotlinx.coroutines.flow.flatMapMerge
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.flow.toList

class IndexerService(private val docs: DocumentApi, private val index: SearchIndex) {
    @OptIn(ExperimentalCoroutinesApi::class)
    suspend fun reindex(ids: List<String>): Int {
        val fetched = ids.asFlow()
            .flatMapMerge(concurrency = 8) { id -> flow { emit(docs.fetch(id)) } }
            .toList()
        index.bulkUpsert(fetched)
        return fetched.size
    }
}

package com.acme.profile

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

class ProfileRepository(private val api: ProfileApi, private val dao: ProfileDao) {
    suspend fun profile(userId: String): Profile = withContext(Dispatchers.IO) {
        dao.find(userId) ?: api.fetchProfile(userId).also { dao.upsert(it) }
    }
}

package com.acme.money

@JvmInline
value class Money(val cents: Long) {
    operator fun plus(other: Money) = Money(cents + other.cents)
    operator fun times(qty: Int) = Money(cents * qty)
    fun format(): String = "%d.%02d".format(cents / 100, cents % 100)
}

