package com.acme.ui

import java.time.LocalDate
import java.time.format.DateTimeFormatter

object DateLabels {
    private val fmt = DateTimeFormatter.ofPattern("d MMM yyyy")
    fun label(date: LocalDate, today: LocalDate): String = when (date) {
        today -> "Today"
        today.minusDays(1) -> "Yesterday"
        else -> date.format(fmt)
    }
}

package com.acme.reports

import kotlinx.coroutines.async
import kotlinx.coroutines.coroutineScope

class ReportAggregator(private val sales: SalesApi, private val refunds: RefundsApi) {
    suspend fun monthly(month: String): MonthlyReport = coroutineScope {
        val s = async { sales.total(month) }
        val r = async { refunds.total(month) }
        MonthlyReport(month, gross = s.await(), refunds = r.await())
    }
}

